f.create_time >= #{query.createdFrom} AND f.create_time < #{query.createdTo}
AND f.file_id = #{query.fileId}
AND f.source_system = #{query.sourceSystem}
AND f.reason_code = #{query.reasonCode}
AND f.access_level = #{query.accessLevel}
AND f.scan_status = #{query.scanStatus}

    AND NOT EXISTS (SELECT 1 FROM t_file_version p
        WHERE p.file_id = f.file_id AND p.version_no > f.current_version_no AND p.version_status = 'CANDIDATE')


    AND EXISTS (SELECT 1 FROM t_file_upload u WHERE u.upload_id = f.upload_id AND u.uploader_id = #{query.uploaderAccountId})
